const env = (t, a, b) => Math.min(1, t / a, (1 - t) / b);   // fade in over a, out over b (fractions of the life)
const make = (flow, n, period, fn) => {
  const g = svg.querySelector('.fc-ps[data-flow="' + flow + '"]');
  const list = Array.from({ length: n }, (_, i) => { const c = document.createElementNS("http://www.w3.org/2000/svg", "circle"); c.setAttribute("class", "fc-p " + flow); g.appendChild(c); return { c, phase: i / n, seed: [rnd(), rnd(), rnd()] }; });
  return { g, list, period, fn };
};
const fanP = (s) => { const fz = F.fanZ[s[0] < 0.5 ? 0 : 1], a = s[1] * 6.283, r = Math.sqrt(s[2]) * F.fanR; return [0, r * Math.cos(a), fz + r * Math.sin(a)]; };
const flows = [
  make("h2", 4, 3.2, (t, s) => ({ p: lerp3(F.h2.from, F.h2.to, t), r: 2.2, a: env(t, 0.25, 0.12) })),
  make("air", 18, 6, (t, s) => { const y = F.yRange[0] + s[0] * (F.yRange[1] - F.yRange[0]), z = F.zRange[0] + s[1] * (F.zRange[1] - F.zRange[0]); return { p: [F.air.x0 + (F.air.x1 - F.air.x0) * t, y, z], r: 1.5, a: 0.8 * env(t, 0.3, 0.06) }; }),
  make("vap", 14, 4.8, (t, s) => { const b = fanP(s); return { p: [F.vapour.x0 + F.vapour.dir * 70 * t, b[1] * (1 + 0.4 * t), b[2] + 34 * t], r: 1.8 + 2.4 * t, a: 0.6 * env(t, 0.12, 0.6) }; }),
  make("cur", 6, 2.6, (t, s, i) => { const l = F.leads[i % 2]; const u = l.sign === "+" ? t : 1 - t; return { p: lerp3(l.root, l.tip, u), r: 1.5, a: l.sign === "+" ? env(t, 0.2, 0.3) : env(t, 0.3, 0.2) }; }),
];
function drawFlows(time) {
  for (const f of flows) {
    f.list.forEach((q, i) => {
      const t = ((time / f.period + q.phase) % 1 + 1) % 1;
      const o = f.fn(t, q.seed, i);
      const [x, y] = iso(o.p, P);
      q.c.setAttribute("cx", x.toFixed(1)); q.c.setAttribute("cy", y.toFixed(1)); q.c.setAttribute("r", o.r.toFixed(2));
      q.c.setAttribute("opacity", Math.max(0, o.a * flowA).toFixed(3));
    });
  }
  const arrows = svg.querySelector(".fc-still"), a = flowA.toFixed(2);
  if (arrows.style.opacity !== a) arrows.style.opacity = a;
}

// ---- selection and readout ----
const all = Object.keys(D.read).filter((id) => id !== "ep");
const rest = () => (narrow.matches ? D.spec : "");   // BRIEF §16: on desktop the spec line has its own place under the title
function select(id) {
  if (id === selected) return;
  selected = id;
  for (const n of nodes) n.el.toggleAttribute("data-on", id !== null && n.piece === id);
  for (const t of tags) t.toggleAttribute("data-on", id !== null && t.dataset.piece === id);
  for (const g of svg.querySelectorAll(".fc-ps")) g.toggleAttribute("data-on", g.dataset.flow === id);
  const isFlow = ["h2", "air", "vap", "cur"].includes(id);
  stage.toggleAttribute("data-flow-on", isFlow);
  if (id === "h2") for (const n of nodes) if (n.el.querySelector(".fc-h2")) n.el.setAttribute("data-on", "");
  for (const p of picks) p.toggleAttribute("data-on", p.dataset.pick === id);
  for (const m of root.querySelectorAll(".fc-more")) m.hidden = true;
  if (id) {
    const [name, text] = D.read[id];
    readout.innerHTML = "";
    readout.append(name);
    const s = document.createElement("span"); s.className = "fc-rtext"; s.textContent = text; readout.append(s);
    const pick = picks.find((p) => p.dataset.pick === id);
    if (narrow.matches && pick) { const m = pick.nextElementSibling; m.textContent = text; m.hidden = false; }
    status.textContent = name + ". " + text;
  } else { readout.textContent = rest(); status.textContent = ""; }
  if (hint) hint.style.visibility = id && !narrow.matches ? "hidden" : "";
}
const mouse = (e) => e.pointerType === "mouse";
parts.addEventListener("pointerover", (e) => { const it = e.target.closest(".it"); if (it && mouse(e)) select(it.dataset.piece); });
parts.addEventListener("pointerleave", (e) => { if (mouse(e)) select(null); });
parts.addEventListener("click", (e) => { const it = e.target.closest(".it"); if (it) { e.stopPropagation(); select(it.dataset.piece); } });
for (const h of svg.querySelectorAll(".fc-hit")) {
  h.addEventListener("pointerenter", (e) => { if (mouse(e)) select(h.dataset.flow); });
  h.addEventListener("pointerleave", (e) => { if (mouse(e)) select(null); });
  h.addEventListener("click", (e) => { e.stopPropagation(); select(h.dataset.flow); });
}
picks.forEach((p, i) => {
  p.addEventListener("pointerenter", (e) => { if (mouse(e)) select(p.dataset.pick); });
  p.addEventListener("click", () => select(selected === p.dataset.pick && narrow.matches ? null : p.dataset.pick));
  p.addEventListener("focus", () => select(p.dataset.pick));
  p.addEventListener("keydown", (e) => {
    if (e.key === "ArrowDown" || e.key === "ArrowRight") { e.preventDefault(); picks[(i + 1) % picks.length].focus(); }
    if (e.key === "ArrowUp" || e.key === "ArrowLeft") { e.preventDefault(); picks[(i - 1 + picks.length) % picks.length].focus(); }
    if (e.key === "Escape") { p.blur(); select(null); }
  });
});
root.querySelector(".fc-lists").addEventListener("pointerleave", (e) => { if (mouse(e) && !root.querySelector(".fc-lists").contains(document.activeElement)) select(null); });
stage.addEventListener("click", () => select(null));
button.addEventListener("click", (e) => { e.stopPropagation(); setApart(!apart); });

// ---- loop: runs while onscreen and moving or flowing ----
let time = 0;
function frame(now) {
  raf = 0;
  const dt = last ? Math.min(0.05, (now - last) / 1000) : 0;
  last = now; clock += dt;
  let moving = false;
  for (const id of D.stagger) moving = steer(piece[id], dt) || moving;
  const home = D.stagger.every((id) => piece[id].x === 0 && !piece[id].pending);
  const goal = home ? 1 : 0;
  flowA = still.matches ? goal : flowA + (goal - flowA) * Math.min(1, dt / 0.15);
  if (Math.abs(flowA - goal) < 0.002) flowA = goal;
  place();
  if (!still.matches) time += dt;
  drawFlows(time);
  const busy = moving || flowA !== goal || (!still.matches && flowA > 0);
  if (busy && visible && !document.hidden) raf = requestAnimationFrame(frame); else last = 0;
}
function wake() { if (!raf && visible && !document.hidden) raf = requestAnimationFrame(frame); }
new IntersectionObserver(([e]) => { visible = e.isIntersecting; wake(); }).observe(stage);
document.addEventListener("visibilitychange", wake);
still.addEventListener("change", wake);
narrow.addEventListener("change", () => { place(); if (!selected) readout.textContent = rest(); });
readout.textContent = rest();
place(); drawFlows(0);
window.__fc = { setApart, select, piece, get apart() { return apart; }, settle() { for (const id of D.stagger) { const s = piece[id]; if (s.pending) { s.target = s.pending.value; s.pending = null; } s.x = s.target; s.v = 0; } flowA = apart ? 0 : 1; place(); drawFlows(time); }, pose(t) { time = t; drawFlows(t); } };
